referenceSolutions.javascript:
export function maximalSquare(matrix            )         {
if(!matrix.length)return 0;const d=Array(matrix[0].length+1).fill(0);let best=0;for(const row of matrix){let diagonal=0;for(let j=1;j<=row.length;j++){const old=d[j];d[j]=row[j-1]===1?1+Math.min(d[j],d[j-1],diagonal):0;best=Math.max(best,d[j]);diagonal=old;}}return best*best;
}

